// src/services/authService.js - Real authentication service
import { api, ApiError } from './api';

class AuthService {
  constructor() {
    this.tokenKey = 'eredes_auth_token';
    this.userKey = 'eredes_user';
  }

  async login(credentials) {
    try {
      if (!credentials.username || !credentials.password) {
        throw new Error('Username and password are required');
      }

      // Call backend login endpoint
      const response = await api.post('/auth/login', {
        nif: credentials.username,
        password: credentials.password,
      });

      if (!response.success) {
        throw new Error(response.error || 'Login failed');
      }

      if (!response.authToken || !response.cookies) {
        throw new Error('Invalid response from authentication service');
      }

      // Store auth data
      localStorage.setItem(this.tokenKey, response.authToken);
      localStorage.setItem(this.userKey, JSON.stringify(response.user));

      return {
        success: true,
        authToken: response.authToken,
        cookies: response.cookies,
        user: response.user,
      };

    } catch (error) {
      console.error('Login error:', error);

      if (error instanceof ApiError) {
        if (error.status === 401) {
          throw new Error('Credenciais inválidas');
        } else if (error.status === 429) {
          throw new Error('Muitas tentativas. Tente novamente mais tarde');
        } else if (error.status >= 500) {
          throw new Error('Erro do servidor. Tente novamente mais tarde');
        }
      }

      throw error;
    }
  }

  async logout() {
    try {
      const token = this.getToken();

      if (token) {
        // Call backend logout endpoint
        await api.post('/auth/logout', {}, {
          headers: {
            'Authorization': `Bearer ${token}`,
          },
        });
      }
    } catch (error) {
      console.error('Logout error:', error);
      // Continue with local logout even if backend call fails
    } finally {
      // Clear local storage
      localStorage.removeItem(this.tokenKey);
      localStorage.removeItem(this.userKey);
    }
  }

  async refreshToken() {
    try {
      const token = this.getToken();

      if (!token) {
        throw new Error('No token to refresh');
      }

      const response = await api.post('/auth/refresh', {}, {
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });

      if (!response.success || !response.authToken) {
        throw new Error('Token refresh failed');
      }

      localStorage.setItem(this.tokenKey, response.authToken);

      return response.authToken;

    } catch (error) {
      console.error('Token refresh error:', error);
      this.logout(); // Clear invalid token
      throw error;
    }
  }

  getToken() {
    return localStorage.getItem(this.tokenKey);
  }

  getUser() {
    const userData = localStorage.getItem(this.userKey);
    return userData ? JSON.parse(userData) : null;
  }

  isAuthenticated() {
    return !!this.getToken();
  }
}

export const authService = new AuthService();
